import numpy as np
import pandas as pd

def metric(data: pd.DataFrame) -> float:
    validities = np.array([0.95, 0.8, 0.85, 0.55])
    wadd_consistent = 0
    tally_ties = 0

    for _, row in data.iterrows():
        a = np.array(row['option_a_ratings'])
        b = np.array(row['option_b_ratings'])

        a_wins = np.sum(a > b)
        b_wins = np.sum(b > a)

        # Focus on trials where Tallying predicts a tie
        if a_wins == b_wins:
            score_a = np.sum(a * validities)
            score_b = np.sum(b * validities)

            if score_a > score_b:
                wadd_choice = 0
            elif score_b > score_a:
                wadd_choice = 1
            else:
                continue

            if row['response'] == wadd_choice:
                wadd_consistent += 1
            tally_ties += 1

    if tally_ties == 0:
        return 0.5
    return float(wadd_consistent / tally_ties)

