    total = 0

    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']

        ttb_choice = -1
        for idx in order:
            if a[idx] > b[idx]:
                ttb_choice = 0
                break
            elif b[idx] > a[idx]:
                ttb_choice = 1
                break

        if ttb_choice != -1:
            if row['response'] == ttb_choice:
                match_count += 1
            total += 1

    if total == 0:
        return 0.5
    return match_count / total

